import "dotenv/config";
import { Client } from "pg";
import { createHash, randomUUID } from "node:crypto";
import { pathToFileURL } from "node:url";
import { z } from "zod";
export async function provisionOperator(
  client: Client,
  id: string,
  expectedSubject: string,
  revoke = false,
) {
  if (
    !z.uuid().safeParse(id).success ||
    !expectedSubject ||
    expectedSubject.length > 255
  )
    throw new Error("ADMIN_BOOTSTRAP_INVALID");
  await client.query("BEGIN");
  try {
    await client.query("SELECT pg_advisory_xact_lock(73461,1)");
    const rows = await client.query(
      'SELECT id,"googleId","isAdmin","isSuspended","deletionRequestedAt" FROM "User" WHERE id=$1 FOR UPDATE',
      [id],
    );
    const u = rows.rows[0];
    if (
      !u ||
      u.googleId !== expectedSubject ||
      (!revoke && (u.isSuspended || u.deletionRequestedAt))
    )
      throw new Error();
    if (revoke ? !u.isAdmin : u.isAdmin) throw new Error();
    if (
      !revoke &&
      (await client.query('SELECT id FROM "User" WHERE "isAdmin"')).rowCount
    )
      throw new Error();
    const requestId = randomUUID(),
      action = revoke ? "ADMIN_REVOKED" : "ADMIN_PROMOTED",
      before = { isAdmin: !!u.isAdmin },
      after = { isAdmin: !revoke };
    const hash = createHash("sha256")
      .update(JSON.stringify([id, action, requestId]))
      .digest("hex");
    await client.query('UPDATE "User" SET "isAdmin"=$2 WHERE id=$1', [
      id,
      !revoke,
    ]);
    await client.query(
      `INSERT INTO "AdminAuditLog" (id,"actorUserId","targetUserId","actorIdSnapshot","targetIdSnapshot",action,"requestId","requestHash",reason,before,after) VALUES ($1,$2,$2,$2,$2,$3,$4,$5,'RECOVERY',$6,$7)`,
      [
        randomUUID(),
        id,
        action,
        requestId,
        hash,
        JSON.stringify(before),
        JSON.stringify(after),
      ],
    );
    await client.query("COMMIT");
    return requestId;
  } catch {
    await client.query("ROLLBACK");
    throw new Error("ADMIN_BOOTSTRAP_DENIED");
  }
}
async function main() {
  const client = new Client({ connectionString: process.env.DATABASE_URL });
  try {
    await client.connect();
    const [operation, id, subject] = process.argv.slice(2);
    if (!["promote", "revoke"].includes(operation)) throw new Error();
    const requestId = await provisionOperator(
      client,
      id,
      subject,
      operation === "revoke",
    );
    console.info("ADMIN_BOOTSTRAP_COMPLETE", requestId);
  } catch {
    console.error("ADMIN_BOOTSTRAP_DENIED");
    process.exitCode = 1;
  } finally {
    await client.end();
  }
}
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href)
  void main();
